const input = $('Var | InputModule').first().json;
const incomingItems = $input.all();

const history = incomingItems
  .map((item) => {
    const row = item.json || {};
    const fields = row.fields && typeof row.fields === 'object' ? row.fields : row;

    const roleRaw = String(fields.Role || '').toLowerCase().trim();
    const role = roleRaw === 'assistant' ? 'assistant' : 'user';
    const content = fields.Content ? String(fields.Content) : '';
    const createdAt = fields.CreatedAt ? String(fields.CreatedAt) : '';

    if (!content) return null;

    return {
      role,
      content,
      createdAt,
    };
  })
  .filter(Boolean)
  .sort((a, b) => new Date(a.createdAt || 0) - new Date(b.createdAt || 0));

const memoryLimit = Number(input.MemoryLimit || 20);
const trimmed = history.slice(-memoryLimit);

const messages = trimmed.map((item) => ({
  role: item.role,
  content: item.content,
}));

messages.push({
  role: 'user',
  content: String(input.UserPrompt || ''),
});

return [
  {
    json: {
      ...input,
      history: trimmed,
      messages,
      memoryDebug: JSON.stringify(messages, null, 2),
    },
  },
];

const items = $input.all();

function safeParseJson(value) {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'object') return value;

  try {
    return JSON.parse(String(value));
  } catch (error) {
    return null;
  }
}

function extractJsonFromMarkdown(text) {
  if (text === undefined || text === null) return null;

  const raw = String(text).trim();

  const fencedMatch = raw.match(/```json\s*([\s\S]*?)\s*```/i);
  if (fencedMatch) {
    try {
      return JSON.parse(fencedMatch[1].trim());
    } catch (error) {
      return null;
    }
  }

  if (
    (raw.startsWith('{') && raw.endsWith('}')) ||
    (raw.startsWith('[') && raw.endsWith(']'))
  ) {
    try {
      return JSON.parse(raw);
    } catch (error) {
      return null;
    }
  }

  return null;
}

return items.map((item) => {
  const wrapper = item.json || {};
  const src = safeParseJson(wrapper.data) || wrapper;

  const usage = src.usage || {};
  const content = Array.isArray(src.content) ? src.content : [];

  const contentText = content
    .map((part) => {
      if (part && typeof part === 'object' && part.text !== undefined) {
        return String(part.text);
      }
      if (typeof part === 'string') {
        return part;
      }
      return '';
    })
    .filter(Boolean)
    .join('\n');

  return {
    json: {
      role: src.role ?? '',
      model: src.model ?? '',
      id: src.id ?? '',
      type: src.type ?? '',
      stop_reason: src.stop_reason ?? '',
      credits_consumed: src.credits_consumed ?? '',
      output_tokens: usage.output_tokens ?? '',
      input_tokens: usage.input_tokens ?? '',
      content_count: content.length || '',
      thinking: src.thinking ?? '',
      content_text: contentText || '',
      parsed_json: extractJsonFromMarkdown(contentText),
      prompt: src.prompt ?? ''
    }
  };
});

const items = $input.all();

function safeParseJson(value) {
  if (value === undefined || value === null) return null;
  if (typeof value === 'object') return value;

  try {
    return JSON.parse(String(value));
  } catch (error) {
    return null;
  }
}

function extractJsonFromMarkdown(text) {
  if (text === undefined || text === null) return null;

  const raw = String(text).trim();

  const fencedMatch = raw.match(/```json\s*([\s\S]*?)\s*```/i);
  if (fencedMatch) {
    return fencedMatch[1].trim();
  }

  if (
    (raw.startsWith('{') && raw.endsWith('}')) ||
    (raw.startsWith('[') && raw.endsWith(']'))
  ) {
    return raw;
  }

  return null;
}

return items.map((item) => {
  const wrapper = item.json || {};
  const src = safeParseJson(wrapper.data) || wrapper;

  const usage = src.usage || {};
  const content = Array.isArray(src.content) ? src.content : [];

  const thinkingBlock = content.find((part) => part && part.type === 'thinking') || {};
  const textBlock = content.find((part) => part && part.type === 'text') || {};

  const thinking = thinkingBlock.thinking ? String(thinkingBlock.thinking) : '';
  const text = textBlock.text ? String(textBlock.text) : '';

  const extractedInnerJson = extractJsonFromMarkdown(text);
  const parsedInnerJson = safeParseJson(extractedInnerJson);

  const prompt = parsedInnerJson?.prompt
    ? String(parsedInnerJson.prompt)
    : text;

  return {
    json: {
      role: src.role || '',
      model: src.model || '',
      id: src.id || '',
      type: src.type || '',
      stop_reason: src.stop_reason || '',
      credits_consumed: Number(src.credits_consumed || 0),

      output_tokens: Number(usage.output_tokens || 0),
      input_tokens: Number(usage.input_tokens || 0),

      content_count: content.length,

      thinking: thinking,
      content_text: text,

      parsed_json: parsedInnerJson,
      prompt: prompt
    }
  };
});
